<script setup lang="ts">
import { ArrowLeft, CheckCircle2, ClipboardCheck, LoaderCircle, Save, XCircle } from '@lucide/vue'
import { onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import api from '../api'
import { useLocaleStore } from '../stores/locale'
const route=useRoute();const router=useRouter();const locale=useLocaleStore();const loading=ref(true);const saving=ref(false);const error=ref('');const exam=ref<any>(null);const students=ref<any[]>([]);const rows=ref<Record<number,string>>({});const summary=ref<any>({present:0,late:0,excused:0,absent:0})
async function load(){try{const r=(await api.get(`/examinations/${route.params.examId}/attendance`)).data;exam.value=r.exam;students.value=r.students||[];summary.value=r.summary||summary.value;const existing=Object.fromEntries((r.attendance||[]).map((item:any)=>[item.student_id,item.status]));rows.value=Object.fromEntries(students.value.map((student:any)=>[student.id,existing[student.id]||'present']))}catch(e:any){error.value=e.response?.data?.message||'Unable to load exam attendance.'}finally{loading.value=false}}
async function save(){saving.value=true;error.value='';try{await api.put(`/examinations/${route.params.examId}/attendance`,{attendance:Object.entries(rows.value).map(([student_id,status])=>({student_id:Number(student_id),status}))});await load()}catch(e:any){error.value=e.response?.data?.message||'Unable to save exam attendance.'}finally{saving.value=false}}
function statusClass(status:string){return status==='present'||status==='late'?'good':status==='absent'?'bad':'neutral'}
onMounted(load)
</script>
<template><div class="app-shell teacher-shell exam-attendance-workspace"><main class="dashboard-main"><header><button class="button secondary back-button" @click="router.push('/teacher/exams')"><ArrowLeft/>{{locale.tr('Back to exams')}}</button></header><div v-if="loading" class="loading-state"><span></span>{{locale.tr('Loading exam attendance…')}}</div><div v-else class="dashboard-content teacher-content"><div class="teacher-page-head"><div><span>{{locale.tr('PHYSICAL EXAM ATTENDANCE')}}</span><h1>{{exam?.title}}</h1><p>{{exam?.exam_date}} · {{locale.tr('Mark the arrival status of every targeted student.')}}</p></div><button class="button primary" :disabled="saving||exam?.status==='locked'" @click="save"><LoaderCircle v-if="saving" class="spin"/><Save v-else/>{{saving?locale.tr('Saving…'):locale.tr('Save attendance')}}</button></div><div v-if="error" class="form-error">{{error}}</div><section class="attendance-summary"><article><CheckCircle2/><b>{{summary.present}}</b><small>{{locale.tr('Present / late')}}</small></article><article><ClipboardCheck/><b>{{summary.excused}}</b><small>{{locale.tr('Excused')}}</small></article><article><XCircle/><b>{{summary.absent}}</b><small>{{locale.tr('Absent')}}</small></article></section><section class="teacher-card exam-attendance-card"><div class="teacher-card-head"><div><small>{{locale.tr('TARGETED STUDENTS')}}</small><h2>{{students.length}} {{locale.tr('students')}}</h2></div><span v-if="exam?.status==='locked'" class="locked-label">{{locale.tr('Locked')}}</span></div><div v-if="!students.length" class="teacher-empty compact"><ClipboardCheck/><b>{{locale.tr('No students targeted')}}</b><p>{{locale.tr('Assign teaching groups to this exam first.')}}</p></div><div v-else class="exam-attendance-table"><div class="exam-attendance-row head"><span>{{locale.tr('Student')}}</span><span>{{locale.tr('Code')}}</span><span>{{locale.tr('Status')}}</span></div><div v-for="student in students" :key="student.id" class="exam-attendance-row"><span><b>{{student.name_en||student.name_ar}}</b></span><span>{{student.student_code}}</span><span class="attendance-status-buttons"><button v-for="status in ['present','late','excused','absent']" :key="status" :disabled="exam?.status==='locked'" :class="[{active:rows[student.id]===status},statusClass(status)]" @click="rows[student.id]=status">{{locale.tr(status)}}</button></span></div></div></section></div></main></div></template>
